#!/usr/bin/env bash
# Launcher of the GDW extension run (spec docs/plans/2026-10-27-gdw-extension-run-spec.md): size tiers by estimated grid
# size (million cells), several processes per tier, then a single-process pass for memory retries and the 45 km
# edge pass. One BLAS / OpenMP thread per process (as r2_global_batch.sh). Logs in the run folder.
# DO NOT EDIT THIS FILE WHILE IT IS RUNNING: bash reads a script while executing it.
# Usage: bash 04_Code/scripts/gdw_ext_batch.sh
cd "$(dirname "$0")/../.." || exit 1
LOG=05_Results/by_date/2026-10-27/gdw_ext_v1/logs; mkdir -p "$LOG"
export PYTHONIOENCODING=utf-8 OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1
run() { .venv/Scripts/python.exe -I 04_Code/scripts/gdw_ext_v1.py "$@" 2>&1 | grep --line-buffered -v "^r2 {"; }
tier() { size=$1; name=$2; n=$3; for i in $(seq 1 "$n"); do run run --size "$size" --part "$i/$n" >> "$LOG/${name}_${i}of${n}.log" & done; wait; }
tier 0:3 small 6
tier 3:10 mid 3
tier 10:100000 large 1
run run >> "$LOG/retry.log"
run retry-edge >> "$LOG/edge.log"
echo "batch finished $(date -Iseconds)" >> "$LOG/batch.log"
